CREATE TABLE IF NOT EXISTS tpay_runtime_control (singleton_id smallint PRIMARY KEY CHECK (singleton_id=1),mode text NOT NULL CHECK (mode IN ('normal','degraded','readonly','maintenance')),message text NOT NULL DEFAULT '',version bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid);
INSERT INTO tpay_runtime_control(singleton_id,mode) VALUES(1,'normal') ON CONFLICT (singleton_id) DO NOTHING;
CREATE TABLE IF NOT EXISTS tpay_runtime_change_requests (id uuid PRIMARY KEY,requested_by uuid NOT NULL,requested_mode text NOT NULL CHECK (requested_mode IN ('normal','degraded','readonly','maintenance')),reason text NOT NULL CHECK (char_length(trim(reason)) BETWEEN 8 AND 1000),request_digest char(64) NOT NULL CHECK (request_digest ~ '^[0-9a-f]{64}$'),required_approvals integer NOT NULL DEFAULT 2 CHECK (required_approvals=2),status text NOT NULL CHECK (status IN ('PENDING','APPROVED','REJECTED','EXPIRED','APPLIED')),created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,applied_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS uq_runtime_change_digest_pending ON tpay_runtime_change_requests(request_digest) WHERE status='PENDING';
CREATE INDEX IF NOT EXISTS idx_runtime_change_status ON tpay_runtime_change_requests(status,created_at DESC);
CREATE TABLE IF NOT EXISTS tpay_runtime_change_approvals (request_id uuid NOT NULL REFERENCES tpay_runtime_change_requests(id) ON DELETE CASCADE,approver_id uuid NOT NULL,approval_digest char(64) NOT NULL CHECK (approval_digest ~ '^[0-9a-f]{64}$'),approved_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(request_id,approver_id));
CREATE TABLE IF NOT EXISTS tpay_admin_audit_events (id uuid PRIMARY KEY,actor_id uuid,action text NOT NULL,target_type text NOT NULL,target_id text,request_digest char(64),metadata jsonb NOT NULL DEFAULT '{}'::jsonb,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_tpay_admin_audit_events_time ON tpay_admin_audit_events(occurred_at DESC);